-- Scholea backend 6/7: projects and collaboration.
--
-- Server-authored times are timestamptz; RPCs emit epoch milliseconds through
-- private.to_ms(). content_updated_at is the client's own clock and stays bigint.

-- ---------------------------------------------------------------------------
-- Projects
-- ---------------------------------------------------------------------------
-- The id is generated by the client (proj_<uuid v4>) and written to its local
-- link record before the first network call, so a retried create is idempotent.
--
-- content is text, not jsonb: it is an opaque blob the server never queries, and
-- jsonb rejects \u0000 escapes, which occur in text extracted from PDFs and
-- would permanently stall that project's sync.
create table public.projects (
  id                 text primary key default ('proj_' || gen_random_uuid()::text)
                     check (id ~ '^proj_[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'),
  title              text not null check (char_length(title) between 1 and 300),
  study_type         text not null check (char_length(study_type) between 1 and 100),
  owner_id           uuid references public.profiles (id) on delete set null,   -- creator; authority is the member role
  content            text,
  rev                integer not null default 0 check (rev >= 0),
  content_updated_at bigint check (content_updated_at >= 0),
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  -- Moves whenever a comment or a review of this project is written (see the
  -- triggers below). Null until the first one. Clients compare it to decide
  -- whether to fetch comments and reviews again.
  collab_updated_at  timestamptz
);

create table public.project_members (
  project_id text not null references public.projects (id) on delete cascade,
  user_id    uuid not null references public.profiles (id) on delete cascade,
  role       text not null default 'editor' check (role in ('viewer', 'editor', 'supervisor', 'owner')),
  added_by   uuid references public.profiles (id) on delete set null,
  added_at   timestamptz not null default now(),
  primary key (project_id, user_id)
);

create index project_members_user_idx on public.project_members (user_id);

-- ---------------------------------------------------------------------------
-- Invitations
-- ---------------------------------------------------------------------------
-- Addressed to an email, not to an account, so inviting never reveals whether
-- the address is registered. Membership is created only when the invitee
-- accepts. Rows are kept after cancel or decline so the daily cap can count
-- them. An owner is never an invitation role: ownership is granted to a member.
create table public.project_invitations (
  id           uuid primary key default gen_random_uuid(),
  project_id   text not null references public.projects (id) on delete cascade,
  email        text not null check (email = lower(email) and length(email) <= 254),
  role         text not null check (role in ('viewer', 'editor', 'supervisor')),
  invited_by   uuid not null references public.profiles (id) on delete cascade,
  status       text not null default 'pending'
               check (status in ('pending', 'declined', 'accepted', 'cancelled', 'expired')),
  created_at   timestamptz not null default now(),
  expires_at   timestamptz not null default now() + interval '30 days',
  responded_at timestamptz
);

-- At most one live invitation per project and address. A declined one still
-- counts as live: to the owner it keeps looking pending until it expires.
create unique index project_invitations_live
  on public.project_invitations (project_id, email) where status in ('pending', 'declined');
create index project_invitations_email
  on public.project_invitations (email) where status = 'pending';
create index project_invitations_inviter_day
  on public.project_invitations (invited_by, created_at);

-- ---------------------------------------------------------------------------
-- Comments, reviews, step ownership, activity
-- ---------------------------------------------------------------------------
-- The comment id may be supplied by the client, which makes a retried upload idempotent.
create table public.project_comments (
  id          uuid primary key default gen_random_uuid(),
  project_id  text not null references public.projects (id) on delete cascade,
  step_id     text not null check (char_length(step_id) between 1 and 200),
  author_id   uuid references public.profiles (id) on delete set null,
  author_name text not null,
  body        text not null check (char_length(body) between 1 and 5000),   -- emitted as "text"
  created_at  timestamptz not null default now()
);

create index project_comments_step_idx on public.project_comments (project_id, step_id, created_at);

-- One sign-off per step. RPCs emit id = project_id || ':' || step_id.
create table public.project_reviews (
  project_id    text not null references public.projects (id) on delete cascade,
  step_id       text not null check (char_length(step_id) between 1 and 200),
  status        text not null check (status in ('approved', 'changes')),
  reviewer_id   uuid references public.profiles (id) on delete set null,
  reviewer_name text not null,
  note          text check (char_length(note) <= 2000),
  created_at    timestamptz not null default now(),
  primary key (project_id, step_id)
);

-- The composite foreign key makes "the step owner is a member" a schema rule
-- and clears ownership when that member is removed.
create table public.step_ownership (
  project_id text not null,
  step_id    text not null check (char_length(step_id) between 1 and 200),
  owner_id   uuid not null,
  primary key (project_id, step_id),
  foreign key (project_id, owner_id)
    references public.project_members (project_id, user_id) on delete cascade
);

-- The contribution ledger. Names are snapshots, so an entry stays readable
-- after its actor has been renamed or removed.
create table public.project_activity (
  id         text primary key default ('act_' || gen_random_uuid()::text),
  project_id text not null references public.projects (id) on delete cascade,
  actor_id   uuid references public.profiles (id) on delete set null,
  actor_name text not null,
  action     text not null,
  detail     text,
  created_at timestamptz not null default now()
);

create index project_activity_project_idx on public.project_activity (project_id, created_at desc);

-- ---------------------------------------------------------------------------
-- collab_updated_at
-- ---------------------------------------------------------------------------
-- Maintained here rather than in each RPC, so no write path can forget it.
-- The value only ever increases, by at least a millisecond (the resolution
-- clients see), even when two writers commit out of order.
create or replace function private.touch_collab_updated_at()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  update public.projects p
     set collab_updated_at = greatest(clock_timestamp(), p.collab_updated_at + interval '1 millisecond')
   where p.id = new.project_id;
  return null;
end
$$;

create trigger project_comments_touch_collab
  after insert or update on public.project_comments
  for each row execute function private.touch_collab_updated_at();

create trigger project_reviews_touch_collab
  after insert or update on public.project_reviews
  for each row execute function private.touch_collab_updated_at();

-- ---------------------------------------------------------------------------
-- Project helpers (private: reachable only from definer functions and policies)
-- ---------------------------------------------------------------------------

-- The member's role on the project, or null when they are not a member.
create or replace function private.project_role_of(p_project_id text, p_user_id uuid)
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select m.role
    from public.project_members m
   where m.project_id = p_project_id
     and m.user_id = p_user_id;
$$;

-- Projects the caller may read. Empty unless the caller is active with a live
-- session, which is how every project policy picks up that check.
create or replace function private.my_project_ids()
returns setof text
language sql
stable
security definer
set search_path = ''
as $$
  select m.project_id
    from public.project_members m
   where m.user_id = (select auth.uid())
     and (select private.is_active());
$$;

-- Call before demoting or removing an owner. Raises 409 last_owner when
-- p_user_id is the only owner left. Locks the owner rows, so two concurrent
-- owner changes cannot each see the other as the remaining owner.
create or replace function private.assert_not_last_owner(p_project_id text, p_user_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform 1
     from public.project_members m
    where m.project_id = p_project_id
      and m.role = 'owner'
      for update;
  if not exists (select 1
                   from public.project_members m
                  where m.project_id = p_project_id
                    and m.role = 'owner'
                    and m.user_id <> p_user_id) then
    perform private.fail('last_owner', 409);
  end if;
end
$$;

-- The name snapshotted into comments, reviews and the activity ledger: the
-- profile name, or the email when no name is set (actor() in the legacy server).
create or replace function private.display_name(p_user_id uuid)
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(
    (select coalesce(nullif(btrim(p.name), ''), p.email)
       from public.profiles p
      where p.id = p_user_id),
    '');
$$;

-- Append to the contribution ledger and touch projects.updated_at.
--
-- content.sync is coalesced: a save every few seconds would otherwise bury the
-- ledger. When the newest entry of the project is the same actor's content.sync
-- from the last 10 minutes, that entry is refreshed (detail and time) instead of
-- a new one being added. One editing session therefore reads as one entry.
create or replace function private.log_activity(
  p_project_id text,
  p_actor_id   uuid,
  p_action     text,
  p_detail     text default null
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_name text := private.display_name(p_actor_id);
  v_now  timestamptz := clock_timestamp();   -- not now(): entries of one transaction keep their order
  v_last record;
begin
  -- Touching the project first takes its row lock, which serialises ledger
  -- writes for one project.
  update public.projects set updated_at = now() where id = p_project_id;

  if p_action = 'content.sync' then
    select a.id, a.actor_id, a.action, a.created_at
      into v_last
      from public.project_activity a
     where a.project_id = p_project_id
     order by a.created_at desc
     limit 1;
    if found
       and v_last.action = 'content.sync'
       and v_last.actor_id = p_actor_id
       and v_last.created_at > v_now - interval '10 minutes' then
      update public.project_activity
         set detail = p_detail, actor_name = v_name, created_at = v_now
       where id = v_last.id;
      return;
    end if;
  end if;

  insert into public.project_activity (project_id, actor_id, actor_name, action, detail, created_at)
  values (p_project_id, p_actor_id, v_name, p_action, p_detail, v_now);
end
$$;

-- The caller's confirmed email, read from auth.users and not from the JWT: a
-- token can carry an old address for its whole lifetime after an email change.
-- Null while the address is unconfirmed, so an unconfirmed address reads nothing.
create or replace function private.current_confirmed_email()
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select lower(u.email)
    from auth.users u
   where u.id = (select auth.uid())
     and u.email_confirmed_at is not null;
$$;
